	public class RangeValidator : LongValidator {
		private long min;
		private long max;

		public void setOriginalValue(long originalLong) {
			EnumDataType enuum = tableModel.getEnum();
			EnumDataType copy = (EnumDataType) enuum.copy(enuum.getDataTypeManager());
			string name = copy.getName(originalLong);
			copy.remove(name);
			min = copy.getMinPossibleValue();
			max = copy.getMaxPossibleValue();
		}

		/* @Override */
		public void validateLong(long oldValue, long newValue)
    {
			if (newValue < min || newValue > max) {
				string minValue = getValueAsString(min);
				string maxValue = getValueAsString(max);
				string message =
					"Valid values are in the range (" + minValue + ", " + maxValue + ")";
				throw new ValidationFailedException(message);
			}
		}

	}

	public class StatusBarValidationMessageListener : ValidationMessageListener {
		/* @Override */
		public void message(string msg) {
			setStatusMessage(msg);
		}
	}

	private abstract class EnumCellEditor : GTableTextCellEditor {
		public EnumCellEditor(JTextField textField) : base(textField)
    {
			textField.addKeyListener(editingKeyListener);
			textField.addActionListener(e => table.editingStopped(null));
		}

		/* @Override */
		public Component getTableCellEditorComponent(JTable table1, object value,
				bool isSelected, int row, int column) {
			setStatusMessage("");
			focus((JTextField) getComponent());
			return base.getTableCellEditorComponent(table1, value, isSelected, row, column);
		}

		/* @Override */
		public bool isCellEditable(EventObject e) {
			if (e is KeyEvent) {
				KeyEvent ke = (KeyEvent) e;
				if (ke.getKeyCode() == KeyEvent.VK_F2) {
					return true;
				}
			}
			return base.isCellEditable(e);
		}

		private KeyListener editingKeyListener = new _Anon_KeyAdapter_2();

		private record CellEditRequest(EnumEditorPanel editorPanel, EnumEntry editedEntry,
				int editCol, KeyEvent e) : Runnable {

			/* @Override */
			public void run() {

				JTable table = editorPanel.table;

				// note: this lookup works because equals() is *not* overridden and any edits are
				// applied to the object in memory so that the default '==' lookup works.
				int row = editorPanel.getRow(editedEntry);
				int col = editCol;
				int rowCount = table.getRowCount();
				switch (e.getKeyCode()) {
					case KeyEvent.VK_TAB:
						bool forward = !e.isShiftDown();
						editNextCell(table, forward, row, col);
						return;
					case KeyEvent.VK_DOWN:
						if (++row == rowCount) {
							row = 0;
						}
						editorPanel.edit(row, col);
						return;
					case KeyEvent.VK_UP:
						if (--row < 0) {
							row = rowCount - 1;
						}
						editorPanel.edit(row, col);
						return;
					default:
						return;
				}

			}

			private void editNextCell(JTable table, bool forward, int row, int col) {

				int columnCount = table.getColumnCount();
				int rowCount = table.getRowCount();
				if (forward) {

					int nextRow = row;
					int nextCol = col + 1;
					if (nextCol == columnCount) {

						// wrap to the next row
						nextCol = 0;
						nextRow++;
						if (nextRow == rowCount) {
							// wrap to the first row
							nextRow = 0;
						}
					}

					editorPanel.edit(nextRow, nextCol);
					return;
				}

				// going backward
				int nextRow = row;
				int nextCol = col - 1;
				if (nextCol < 0) {
					nextCol = columnCount - 1;

					nextRow--;
					if (nextRow < 0) {
						nextRow = rowCount - 1;
						nextCol = columnCount - 1;
					}
				}

				editorPanel.edit(nextRow, nextCol);
			}

		}
	}

